import sys

def main():
    import sys
    import bisect

    def readints():
        return list(map(int, sys.stdin.read().split()))

    data = readints()
    n = data[0]
    a = data[1:]

    # Find the longest increasing subsequence
    lis = []
    moves = []

    for i, x in enumerate(a):
        pos = bisect.bisect_left(lis, x)
        if pos == len(lis):
            lis.append(x)
            moves.append('L' if pos == i else 'R')
        else:
            lis[pos] = x
            moves.append('L' if pos == i else 'R')

    # Determine the correct moves
    result_moves = []
    lis_set = set(lis)
    left_index = 0
    right_index = n - 1

    for x in lis:
        while a[left_index] not in lis_set:
            left_index += 1
        while a[right_index] not in lis_set:
            right_index -= 1

        if a[left_index] == x:
            result_moves.append('L')
            left_index += 1
        else:
            result_moves.append('R')
            right_index -= 1

    print(len(lis))
    print(''.join(result_moves))

if __name__ == "__main__":
    main()
